TWComponent.script:
tw.local.userTeams = new tw.object.listOf.String();

for(var i=0;i<tw.system.org.findUserByName(tw.local.loggedInUser).roles.listLength;i++)
{
	tw.local.userTeams[i] = tw.system.org.findUserByName(tw.local.loggedInUser).roles[i].name;
}
log.info("all roles: "+tw.local.userTeams);

for(i=0;i<tw.local.userTeams.listLength;i++)
{
	if(tw.local.userTeams[i] != "" && tw.local.userTeams[i] != null)
	{
	var newString = tw.local.userTeams[i].substring(0,2);
	if(newString == "BR")
	{
	
		tw.local.initiator = tw.epv.userRole.branch;
		tw.local.branchCode = tw.local.userTeams[i];
		tw.local.branchSeq = tw.local.userTeams[i].substring(2,5);
		log.info("Branch Code#: "+tw.local.branchCode);
		log.info("Branch seq#: "+tw.local.branchSeq);
		break;
	}
	else
	{
		
		tw.local.initiator = tw.epv.userRole.hub;
		var splittedArray = tw.local.userTeams[i].split('_',4);
		if(splittedArray[0] == "BPM" && (splittedArray[1] == "ODC" || splittedArray[1] == "IDC" )&& splittedArray[2] == "HUB")
		{
			tw.local.hubCode = splittedArray[3];
			log.info("split array #: "+splittedArray);
			break;
		}
	}
	}
}


